// v35.xx (cw-fewermsg), HIS COMPLAINT (2026-10-27): "there are too many messages coming in to the player", and on the plan: "You need to figure out what works".
// The quiet hud put each line in one place; this cuts how many lines there are. ONLY FIVE KINDS OF LINE REACH THE SCREEN: (a) danger to you now (seen, shot at,
// a siege, a lock-on, low health: the alert lane), (b) extraction (called, inbound, missed, a ring closing, the raid clock), (c) your teammate (down, revived,
// extracted, left, a gift), (d) money or a contract or goal done, and (e) the answer to something you tried that did not work (health full, bandages stop at 85,
// no x left), one short line. Everything else (a codex entry, location revealed, weather and fog, running slowly, a golden enemy, a stronghold, a discovery, lore,
// chatter, system lines, progress counts such as notoriety) is said into the run log (G.msgLog) and drawn nowhere. msgReach() reads the kind and the words and
// gives the letter, or '' for a cut line; o.reach names it outright (0 cuts it). The kill feed, the medal copy and the world label copies (cw-feedall, his order
// 2026-10-15: every word on screen also in the feed) leave the left feed too (MSGLEAN): a kill and its figure show on the target, a medal over the cursor ring,
// a label where it rose. The hub floor is not a raid and keeps every line. The list, call site by call site: tools/handoff/console/notes/raid-messages.md.
var MSGLEAN=1, FEEDGAP=2.5, FEEDWAIT=4, ALERTAGAIN=20;
var MSGCUTA=/^(NOTORIETY |CONVOY MOVING$|MACHINE CONVOY$|COOLANT RUPTURE$|GATE BREACHED$|YOUR RIVAL IS UP TOP$)/;
var MSGOBJ=/^(CONTRACT DONE|CONTRACT ITEM NEARBY|GOAL DONE.*|GUN UPGRADED|CACHE MARKED|KEYCARD DROPPED|.+ IS DEAD|.+ DESTROYED|\d+ MINUTES? LEFT)$/;
var MSGKEEP=[
  ['e',/^(HEALTH FULL|ALREADY (HEALING|APPLYING|SLOTTING)|NOT WHILE DOWN|NO .+|NOTHING TO (USE|PICK UP)|.+ STOPS? AT \d+|TOO TIRED TO ROLL|THROW BLOCKED|THROW THE ONE IN YOUR HAND FIRST|MOVE IT TO THE BACKPACK FIRST|ISSUED GEAR STAYS IN YOUR HANDS|CANNOT .+|NOT IN BACKPACK|SLOT .+ TAKES GUNS ONLY|GUNS GO ON KEYS .+|ITEMS GO ON THE WHEEL|GUN SLOT \d+ EMPTY|EMPTY SLOT|STOP FIRST|ARMOUR FULL|NEED .+|HE NEEDS .+|NOT ENOUGH .+|HE WANTS NOTHING YOU CARRY|SELF-REVIVE SPENT.*|AIR STRIKE \d+%|WARDEN ARMOUR|BULWARK SHIELD|MAX TIER|CONTROLLER DISCONNECTED|WALL GLITCH SAVED TO RUN REPORT|ERROR SAVED TO YOUR RUN REPORT|FEEDBACK (SAVED|COPIED|NOT SAVED)|SUPERHOT (ON|OFF|FOLLOWS THE HOST)|PICK OTHER INITIALS|SELECT A HEAL|.+ (JAMMED|EMPTY|ARMOUR FULL|DOES NOT NEED IT|ALREADY HEALING|COULD NOT TAKE IT|MOVED AWAY|IS SEARCHING|TO BACKPACK))$/],
  ['a',/^(MACHINE ALERT|OVERSEER RETURNS)$/],
  ['b',/^(EXTRACTION \S+ IS CLOSED|PILLAGER BOT CALLED EXTRACTION)$/],
  ['c',/^(.+ RECEIVED|GAVE .+ TO .+|TOOK .+ FROM .+|PLATE FROM .+|.+ PATCHED YOU UP|TAKING IT)$/],
  ['d',/^(SOLD \d+ ITEMS?|SURVIVOR EXTRACTED)$/]
];
var MSGKEYS={loanstash:'e',needhint:'d',selheal:'e',arcxout:'c',cdone:'d'};
function msgReach(m,k,o){
  var s, key=(o&&o.key)?String(o.key):'', i;
  if(o&&o.reach!==undefined) return o.reach||'';
  if(k==='pick'||(G&&G.hubFloor)) return 'd';
  if(MSGKEYS.hasOwnProperty(key)) return MSGKEYS[key];
  s=String(m).toUpperCase().replace(/[.\s]+$/,'');
  if(k==='crit'||k==='warn') return MSGCUTA.test(s)?'':'a';
  if(k==='ext') return (/^(EXTRACT|KNOCKED DOWN)/).test(s)?'b':'d';
  if(k==='ally') return (/^THE PEDDLER /).test(s)?'':'c';
  if(k==='obj') return MSGOBJ.test(s)?((/MINUTES? LEFT$/).test(s)?'b':'d'):'';
  if(G&&G.paused&&(k==='sys'||k==='info')) return 'e';   // a menu answer under the co-op overlay pause (under the solo pause say() hands it to the answer line first)
  for(i=0;i<MSGKEEP.length;i++) if(MSGKEEP[i][1].test(s)) return MSGKEEP[i][0];
  return '';
}
function say(m,kind,o){

// v35.xx (cw-fewermsg): a line of none of the five kinds is in the run log and nowhere else; danger and an answer go into the feed at once, the rest take
// their turn there (feedAdd, one new line every 2.5 s)
var _rc=msgReach(m,k,o); if(!_rc) return;
try{ feedSay(m,k,o,(_rc==='a'||_rc==='e')?'':_rc); }catch(_fsy){}

// v35.xx (cw-fewermsg): AT MOST ONE NEW FEED LINE EVERY 2.5 S. A line that would be new (it joins no line up) and is not danger or an answer (o.cap set)
// waits in F.q while the last new line is under 2.5 s old; feedTick lets the next one in, and drops one that waited over 4 s unless it is money (cap 'd').
// A line said again while it waits takes its own place in the queue, not a second one.
if(o&&o.cap&&now-(F.lastNew===undefined?-1e9:F.lastNew)<FEEDGAP){
  F.q=F.q||[];
  for(i=0;i<F.q.length;i++) if((key&&F.q[i].key===key)||(!key&&!F.q[i].key&&F.q[i].txt===txt)){ F.q[i].segs=segs; F.q[i].txt=txt; F.q[i].o=o; return null; }
  F.q.push({segs:segs,fk:fk,o:o,key:key,txt:txt,at:now});
  return null;
}
F.lastNew=now;
ln={id:(F.seq=(F.seq|0)+1),fk:fk||'info',segs:segs,txt:txt

function feedTick(dt){
  var F=G&&G.fd, i, e, o2, k;
  if(!F) return;
  F.t+=dt;
  if(!F.q||!F.q.length) return;   // v35.xx (cw-fewermsg): the lines waiting their turn (feedAdd)
  for(i=F.q.length-1;i>=0;i--) if(F.t-F.q[i].at>FEEDWAIT&&F.q[i].o.cap!=='d') F.q.splice(i,1);
  if(!F.q.length||F.t-(F.lastNew===undefined?-1e9:F.lastNew)<FEEDGAP) return;
  e=F.q.shift(); o2={}; for(k in e.o) o2[k]=e.o[k]; o2.cap='';
  feedAdd(e.segs,e.fk,o2);
}

// v35.xx (cw-fewermsg): the same warning with no key, drawn in the last 20 s, is not drawn again (PILLAGER BOT REINFORCEMENTS came six times in three minutes
// of the measured raid). A keyed warning (LOCKED ON, the Crier) and every crit still draw each time.
if(k==='warn'&&!key&&G.alertSeen&&G.alertSeen.hasOwnProperty(m)&&now-G.alertSeen[m]<ALERTAGAIN) return;
if(!a||k==='crit'||(MSGK[k].r>=MSGK[msgKind(a.k)].r&&now-a.at>=ALERTMIN)){ alertQDrop(m,key); alertShow(m,k,o,now); return; }

// v35.xx (cw-fewermsg): the box a pickup row belongs to, as a number (a row never holds the box itself)
var PICKBOX={m:(typeof WeakMap==='function')?new WeakMap():null,n:0};
function pickBoxId(ct){ var id; if(!ct||typeof ct!=='object'||!PICKBOX.m) return 0; id=PICKBOX.m.get(ct); if(!id){ id=++PICKBOX.n; PICKBOX.m.set(ct,id); } return id; }
function pickSay(m,o){

if(o&&o.key){ for(i=0;i<q.length;i++){ r=q[i]; if(r.key===o.key&&r.T>0){ r.m=String(m); r.sub=o.sub?String(o.sub):''; if(o.c) r.c=o.c; r.T=PICKLIFE; return; } } }
// v35.xx (cw-fewermsg): ONE ROW PER SEARCH. A box gave one row per item, about forty rows in three minutes of the measured raid. An item out of a box
// (grantLoot, o.box) joins the box's own row while it is up: the best find is named (an item a contract needs first, else the most valuable) and the detail
// is the count and the worth, +6 ITEMS $340 ($ only in a CAREER raid). A gun keeps its own row (its slot tag says where it went), and so does a loose pickup.
var bx=(o&&o.box&&it&&ITEMS[it]&&!ITEMS[it].gk)?pickBoxId(o.box):0, nd=function(x){ return !!(G.need&&G.need[x]>0); };
if(bx){
  for(i=0;i<q.length;i++){
    r=q[i];
    if(r.box!==bx||!(r.T>0)) continue;
    r.its+=n; r.val+=ival(it)*n;
    if((nd(it)&&!nd(r.item))||(nd(it)===nd(r.item)&&ival(it)>r.bv)){ r.item=it; r.m=String(m); r.c=(o&&o.c)||''; r.bv=ival(it); }
    r.tag=''; r.n=1; r.sub='+'+r.its+' ITEMS'+(G.arcade?'':'  $'+r.val.toLocaleString());
    r.T=PICKLIFE; if(i<q.length-1){ q.splice(i,1); q.push(r); }
    return;
  }
}

